#!/usr/bin/env node
const https = require('https');

const AUTH = 'Bearer gk_live_79414cc5d34021a6.f48b009c9ed9470d05fbec8f4ef919f4d657e7a15d91347a';
const CLIENT_ID = 'cli_a1b2c3d4e5f6789012345678abcdef90';

function fetchPage(sinceId) {
  return new Promise((resolve, reject) => {
    const path = `/open/api/v1/resource/note/list?since_id=${sinceId}`;
    const options = {
      hostname: 'openapi.biji.com',
      path,
      method: 'GET',
      headers: {
        'Authorization': AUTH,
        'X-Client-ID': CLIENT_ID,
        'Accept': 'application/json'
      }
    };
    const req = https.request(options, (res) => {
      let data = '';
      res.on('data', chunk => data += chunk);
      res.on('end', () => {
        try {
          const safe = data.replace(/"(id|note_id|next_cursor|parent_id|follow_id|live_id)"\s*:\s*(\d+)/g, '"$1":"$2"');
          resolve(JSON.parse(safe));
        } catch(e) {
          reject(e);
        }
      });
    });
    req.on('error', reject);
    req.end();
  });
}

// Categories
const openclaw_notes = [];  // G0P1Z51J
const education_notes = [];  // EJX1r7bn
const chip_notes = [];      // 9YeBam0m
const skip_notes = [];
const all_scanned = [];

const SKIP_PREFIXES = ['每日发芽报告', '每日备份报告', '每日退租报告'];

function isSkippable(title) {
  if (!title || title.trim() === '') return true;
  for (const p of SKIP_PREFIXES) {
    if (title.includes(p)) return true;
  }
  return false;
}

function categorize(note) {
  const title = note.title || '';
  const content = (note.content || '').toLowerCase();
  const tags = (note.tags || []).map(t => (typeof t === 'string' ? t : t.name || '').toLowerCase());
  const combined = (title + ' ' + content + ' ' + tags.join(' ')).toLowerCase();

  // OpenClaw KB keywords
  const openclaw_kw = [
    'openclaw', 'claude skills', 'skill-creator', 'get笔记', 'feishu', '飞书',
    'ai agent', '提示词', 'prompt', '工作流', 'automation', 'mcp',
    '笔记管理', '知识库', '笔记整理', 'ai工具', '效率工具', '生产力工具',
    'claude code', 'anthropic', 'agent skill', 'skill设计'
  ];

  // Education KB keywords
  const education_kw = [
    '中考', '初中', '初二', '女儿', '学习', '学习方法', '英语', '数学',
    '语文', '物理', '化学', '生物', '地理', '历史', '道法', '政治',
    '成绩', '分数', '备考', '复习', '错题', '周深', '亲子', '青春期',
    '家庭教育', '家长', '孩子教育', '中考备考', '中考复习', '语数英'
  ];

  // Chip KB keywords
  const chip_kw = [
    '芯片', '半导体', '晶圆', '光刻', '封装', '测试', 'fabless', 'ic设计',
    '集成电路', 'ai芯片', 'gpu', 'nvidia', '英伟达', 'amd', 'intel',
    '芯片行业', '半导体设备', '半导体材料', '晶圆代工', 'foundry',
    '中芯国际', '华虹', '台积电', 'tsmc', '芯片制造', '芯片封装',
    '芯片测试', '质量管控', 'quality', '质量管理', '供应商质量',
    'quality management', 'qm', '供应商', '外协', '代工厂'
  ];

  let score_openclaw = 0, score_education = 0, score_chip = 0;

  for (const kw of openclaw_kw) {
    if (combined.includes(kw)) score_openclaw++;
  }
  for (const kw of education_kw) {
    if (combined.includes(kw)) score_education++;
  }
  for (const kw of chip_kw) {
    if (combined.includes(kw)) score_chip++;
  }

  // Prefer education if contains education-related tags
  const tagNames = (note.tags || []).map(t => typeof t === 'string' ? t : t.name || '').join(',');
  if (tagNames.includes('女儿') || tagNames.includes('中考') || tagNames.includes('初中') || tagNames.includes('学习')) {
    score_education += 3;
  }

  // Chip note type ref with chip tags
  if (tagNames.toLowerCase().includes('芯片') || tagNames.includes('半导体')) {
    score_chip += 5;
  }

  const threshold = 2;
  const results = [];
  if (score_openclaw >= threshold) results.push({note, bucket: 'openclaw', score: score_openclaw});
  if (score_education >= threshold) results.push({note, bucket: 'education', score: score_education});
  if (score_chip >= threshold) results.push({note, bucket: 'chip', score: score_chip});

  return results;
}

async function main() {
  let cursor = '1903407802320327056';
  let pagesScanned = 0;
  const totalPages = 25;

  console.error(`Starting scan from cursor: ${cursor}`);
  console.error(`Will scan ${totalPages} pages...`);

  while (pagesScanned < totalPages) {
    try {
      const result = await fetchPage(cursor);
      if (!result.success) {
        console.error(`Page ${pagesScanned + 1} failed:`, result.error);
        break;
      }

      const notes = result.data.notes || [];
      const hasMore = result.data.has_more;
      const nextCursor = result.data.next_cursor;

      console.error(`Page ${pagesScanned + 1}: got ${notes.length} notes, has_more=${hasMore}, next_cursor=${nextCursor}`);

      for (const note of notes) {
        const title = note.title || '';

        if (isSkippable(title)) {
          skip_notes.push({note_id: note.note_id, title, reason: 'skipped_prefix_or_empty'});
          all_scanned.push({note_id: note.note_id, title, skipped: true});
          continue;
        }

        const categories = categorize(note);

        if (categories.length === 0) {
          all_scanned.push({note_id: note.note_id, title, skipped: false, buckets: []});
        } else {
          for (const cat of categories) {
            if (cat.bucket === 'openclaw') openclaw_notes.push({note_id: note.note_id, title, score: cat.score});
            else if (cat.bucket === 'education') education_notes.push({note_id: note.note_id, title, score: cat.score});
            else if (cat.bucket === 'chip') chip_notes.push({note_id: note.note_id, title, score: cat.score});
          }
          all_scanned.push({note_id: note.note_id, title, skipped: false, buckets: categories.map(c => c.bucket)});
        }
      }

      if (!hasMore || !nextCursor) {
        console.error('No more pages');
        break;
      }

      cursor = nextCursor;
      pagesScanned++;

      // Small delay to avoid rate limiting
      await new Promise(r => setTimeout(r, 200));
    } catch(e) {
      console.error(`Error on page ${pagesScanned + 1}:`, e.message);
      break;
    }
  }

  console.error(`\nScan complete: ${pagesScanned} pages, ${all_scanned.length} non-skipped notes`);
  console.error(`OpenClaw candidates: ${openclaw_notes.length}`);
  console.error(`Education candidates: ${education_notes.length}`);
  console.error(`Chip candidates: ${chip_notes.length}`);
  console.error(`Skipped: ${skip_notes.length}`);

  // Deduplicate
  const dedup = (arr) => {
    const seen = new Set();
    return arr.filter(n => {
      if (seen.has(n.note_id)) return false;
      seen.add(n.note_id);
      return true;
    });
  };

  const openclaw_unique = dedup(openclaw_notes).sort((a,b) => b.score - a.score);
  const education_unique = dedup(education_notes).sort((a,b) => b.score - a.score);
  const chip_unique = dedup(chip_notes).sort((a,b) => b.score - a.score);

  // Output results
  const output = {
    scanned_pages: pagesScanned,
    total_scanned: all_scanned.length,
    skipped_count: skip_notes.length,
    openclaw: openclaw_unique,
    education: education_unique,
    chip: chip_unique,
    all_scanned_titles: all_scanned.map(n => ({note_id: n.note_id, title: n.title, buckets: n.buckets}))
  };

  console.log(JSON.stringify(output, null, 2));
}

main().catch(console.error);

