function addToKB(topicId, noteIds) {
  return new Promise((resolve, reject) => {
    const body = JSON.stringify({ topic_id: topicId, note_ids: noteIds });
    const options = {
      hostname: 'openapi.biji.com',
      path: '/open/api/v1/resource/knowledge/note/batch-add',
      method: 'POST',
      headers: {
        'Authorization': AUTH,
        'X-Client-ID': CLIENT_ID,
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(body)
      }
    };
    const req = https.request(options, (res) => {
      let data = '';
      res.on('data', chunk => data += chunk);
      res.on('end', () => {
        try {
          const safe = data.replace(/"(id|note_id|next_cursor|parent_id|follow_id|live_id)"\s*:\s*(\d+)/g, '"$1":"$2"');
          resolve(JSON.parse(safe));
        } catch(e) {
          resolve({ raw: data });
        }
      });
    });
    req.on('error', reject);
    req.write(body);
    req.end();
  });
}

async function main() {
  const results = {};

  // Process in batches of 20 (API limit)
  const batchSize = 20;

  async function processKB(name, kbId, ids) {
    // Deduplicate
    const unique = [...new Set(ids)];
    console.error(`\n[${name}] Adding ${unique.length} unique notes to KB ${kbId}...`);
    const batches = [];
    for (let i = 0; i < unique.length; i += batchSize) {
      batches.push(unique.slice(i, i + batchSize));
    }

    let success = 0, failed = 0, skipped = 0;
    for (const batch of batches) {
      try {
        const result = await addToKB(kbId, batch);
        if (result.success) {
          success += batch.length;
          console.error(`  Batch OK: added ${batch.length} notes`);
        } else {
          console.error(`  Batch failed:`, result.error);
          failed += batch.length;
        }
      } catch(e) {
        console.error(`  Error:`, e.message);
        failed += batch.length;
      }
      await new Promise(r => setTimeout(r, 500));
    }
    results[name] = { total: unique.length, success, failed, skipped };
  }

  await processKB('openclaw', KB.openclaw, openclaw_ids);
  await new Promise(r => setTimeout(r, 1000));
  await processKB('education', KB.education, education_ids);
  await new Promise(r => setTimeout(r, 1000));
  await processKB('chip', KB.chip, chip_ids);

  console.log('\n=== MIGRATION SUMMARY ===');
  console.log(JSON.stringify(results, null, 2));
}

main().catch(console.error);
